#include <pcre2.h>
#include <stdio.h>
#include <stdlib.h>

static size_t allocation_count;
static size_t fail_at;
static void *controlled_malloc(PCRE2_SIZE size, void *unused)
{
    (void)unused;
    ++allocation_count;
    if (fail_at && allocation_count == fail_at)
        return NULL;
    return malloc(size);
}
static void controlled_free(void *ptr, void *unused)
{
    (void)unused;
    free(ptr);
}
int main(void)
{
    const PCRE2_UCHAR pattern[] = { 'a', 0 };
    const PCRE2_UCHAR subject[] = { 'a', 0 };
    for (size_t failure = 1; failure < 100; ++failure) {
        fail_at = 0;
        pcre2_general_context *general = pcre2_general_context_create(controlled_malloc, controlled_free, NULL);
        pcre2_compile_context *context = pcre2_compile_context_create(general);
        int error;
        PCRE2_SIZE offset;
        pcre2_code *code = pcre2_compile(pattern, 1, PCRE2_UTF, &error, &offset, context);
        if (!code)
            return 2;
        pcre2_match_data *data = pcre2_match_data_create_from_pattern(code, general);
        allocation_count = 0;
        fail_at = failure;
        int jit = pcre2_jit_compile(code, PCRE2_JIT_COMPLETE | PCRE2_JIT_PARTIAL_SOFT | PCRE2_JIT_PARTIAL_HARD);
        fail_at = 0;
        int complete = pcre2_jit_match(code, subject, 1, 0, 0, data, NULL);
        int soft = pcre2_jit_match(code, subject, 1, 0, PCRE2_PARTIAL_SOFT, data, NULL);
        int hard = pcre2_jit_match(code, subject, 1, 0, PCRE2_PARTIAL_HARD, data, NULL);
        pcre2_match_data_free(data);
        pcre2_code_free(code);
        pcre2_compile_context_free(context);
        pcre2_general_context_free(general);
        if (jit != 0 && complete >= 0 && (soft == PCRE2_ERROR_JIT_BADOPTION || hard == PCRE2_ERROR_JIT_BADOPTION)) {
            printf("PARTIAL_JIT_RETAINED failure_allocation=%zu jit_result=%d complete=%d partial_soft=%d partial_hard=%d\n", failure, jit, complete, soft, hard);
            return 0;
        }
    }
    puts("NO_PARTIAL_JIT_OBSERVED");
    return 1;
}

