#include <dlfcn.h>
#include <stdio.h>
#include <string.h>

int main(int argc, char **argv)
{
    if (argc != 2)
        return 2;
    if (strcmp(argv[1], "zlib") == 0) {
        void *library = dlopen("/usr/lib/libz.1.dylib", RTLD_NOW | RTLD_LOCAL);
        if (!library)
            return 3;
        const char *(*version)(void) = dlsym(library, "zlibVersion");
        unsigned long (*combine)(long long) = dlsym(library, "crc32_combine_gen64");
        Dl_info info;
        if (!version)
            return 4;
        dladdr((void *)version, &info);
        printf("zlibVersion=%s image=%s crc32_combine_gen64=%s\n", version(), info.dli_fname, combine ? "present" : "absent");
        fflush(stdout);
        if (combine)
            printf("negative_length_result=%lu\n", combine(-1));
        return 0;
    }
    if (strcmp(argv[1], "dbus") == 0) {
        const char *names[] = {"libdbus-1.3.dylib", "libdbus-1.2.dylib", "libdbus-1.dylib"};
        for (unsigned i = 0; i < 3; ++i) {
            void *library = dlopen(names[i], RTLD_NOW | RTLD_LOCAL);
            if (!library || !dlsym(library, "dbus_connection_open_private")) {
                printf("candidate=%s loadable=0\n", names[i]);
                if (library)
                    dlclose(library);
                continue;
            }
            void (*version)(int *, int *, int *) = dlsym(library, "dbus_get_version");
            int major = -1, minor = -1, micro = -1;
            Dl_info info;
            if (version) {
                version(&major, &minor, &micro);
                dladdr((void *)version, &info);
                printf("candidate=%s loadable=1 version=%d.%d.%d image=%s\n", names[i], major, minor, micro, info.dli_fname);
            }
            return version ? 0 : 5;
        }
        return 0;
    }
    return 2;
}
